// Types of the agent loop (spec section 13): the InvestigationResult and the pieces it is made of. Meter kWh are SAMPLE data.
import type { Decomp, HypothesisId, HypothesisResult } from "./hypotheses/types.ts";
import type { Evidence } from "./evidence.ts";
import type { Fact } from "./facts.ts";
import type { Answer, VerifyError } from "./verifier.ts";
import type { Recommendation, TariffComparison } from "./recommend.ts";
import type { Route } from "./provider_shared.ts";
import type { DateWindow } from "./windows.ts";
import type { MarkovianReport } from "./investigate_markovian.ts";

export const INTENT_TYPES = ["why_cost_change", "why_spike_day", "why_emissions", "what_to_change"] as const;
export type IntentType = (typeof INTENT_TYPES)[number];

export interface Intent {
  type: IntentType;
  requestedSites: string[];                   // as written by the model or the user ("Brixton", "site 2", "ALL")
  dates: string[];                            // YYYY-MM-DD
  source: "llm" | "fallback";                 // fallback: deterministic keyword rules after the model failed twice
}

export interface ExtraSql {
  purpose: string; sql: string;
  status: "ran" | "rejected" | "failed";
  reason?: string;                            // why it was rejected by the guard or failed in Zetaris
  evidence?: string; rows?: number;
}
export interface Plan {
  hypotheses: HypothesisId[];                 // in run order, including the ones the system added
  added: HypothesisId[];                      // added by code: H7-H9 data checks, and the tests the question type needs
  dropped: string[];                          // ids the model proposed that are not in the catalog
  extraSql: ExtraSql[];
  rationale: string;
  source: "llm" | "default";
}

export interface LlmCall { step: string; route?: Route; error?: string; wallMs?: number; rejected?: string }   // rejected: why the reply could not be used, with the start and end of its text   // wallMs: the whole call as the agent saw it, including a Meterless attempt that timed out before the fallback answered
export interface Timings { total: number; [step: string]: number }   // milliseconds

export interface Verification {
  passed: boolean; attempts: number; mode: "llm" | "template";
  errors: string[];                           // why the model's last attempt failed (empty when an LLM answer passed); template runs append their own check
  errorDetail: VerifyError[];
  history: { attempt: number; errors: string[]; repairs: string[] }[];   // every failed narrative attempt with its errors (what the corrections fixed)
  repairs: string[];                          // repairs code applied to the accepted answer (digits turned into placeholders, sentences dropped for status contradictions)
}

export interface ScopeInfo { label: string; sites: { id: string; name: string }[]; windowA: DateWindow; windowB: DateWindow }

/** The decomposition without the per-slot arrays (those stay in the evidence store / Zetaris). */
export type DecompositionSummary = Omit<Decomp, "windowA" | "windowB" | "aligned"> & { slotsAligned: number; slotsExpected: number };

export interface InvestigationResult {
  question: string;
  intent: Intent;
  scope: ScopeInfo;
  decomposition: DecompositionSummary;
  plan: Plan;
  results: HypothesisResult[];
  evidence: Evidence[];
  facts: Fact[];
  recommendation: { loadShift: Recommendation | null; tariff: TariffComparison | null };
  answer: Answer;
  verification: Verification;
  llmCalls: LlmCall[];
  timings: Timings;
  notes: string[];
  sampleDataNote: string;
  memory?: MemoryReport;                      // present when the investigation ran with H-MEM
  engine?: "markovian" | "plain";             // how the LLM part ran
  markovian?: MarkovianReport;                // the chunks of the Markovian chain with their tokens (engine "markovian")
}
/** What H-MEM did in this investigation: memories recalled at the start (each is an M# fact) and causes written at the end. */
export interface MemoryReport {
  query: string; embedRoute: string; recallMs: number;
  recalled: { id: string; factId: string; relevance: number; origin: "user" | "agent"; site?: string; learnedAt: string; text: string; citedIn: number }[];   // citedIn: answer items that cite its M#
  written: { id: string; hypothesis: string; text: string; skipped: boolean }[];                                                                                // skipped: the same cause for the same windows was already remembered
}
export interface ClarificationResult { question: string; clarification: string; knownSites: { id: string; name: string }[]; llmCalls: LlmCall[]; timings: Timings }
export type InvestigateOutcome = InvestigationResult | ClarificationResult;
export const isClarification = (o: InvestigateOutcome): o is ClarificationResult => "clarification" in o;

export const SAMPLE_NOTE = "Meter kWh are SAMPLE data (synthetic, Crumb & Co); Agile prices (Octopus), carbon intensity (NESO) and temperatures (Open-Meteo) are real public data.";

// Progress events of an investigation, for a live UI: step started / finished (with milliseconds), evidence created, each LLM call with its route,
// each hypothesis result. `investigate(question, { onEvent })` calls the listener synchronously; a throwing listener never breaks the run.
import type { Evidence } from "./evidence.ts";
import type { LlmCall } from "./agent_types.ts";

export type StepName = "sites" | "intent" | "plan" | "data" | "hypotheses" | "recommend" | "extraSql" | "facts" | "narrative" | "template" | "memory";
export type ProgressEvent =
  | { type: "step"; step: StepName; status: "started" | "finished"; ms?: number }
  | { type: "evidence"; evidence: { id: string; hypothesisId: string; title: string; rowCount: number; zetarisRunId: string; sources: Evidence["sources"] } }
  | { type: "hypothesis"; id: string; name: string; status: string }
  | { type: "llm"; call: LlmCall }
  | { type: "memory"; action: "recall"; query: string; count: number; ids: string[]; route: string; ms: number }                // H-MEM recall at the start
  | { type: "memory"; action: "write"; written: { id: string; hypothesis: string }[]; skipped: number }                  // confirmed causes written after the answer
  | { type: "chunk"; id: number; kind: string; label: string; ms: number; llmCalls: number; inputTokens: number; outputTokens: number; carryoverTokens: number; route: string | null }   // one chunk of the Markovian chain finished (tokens estimated, chars/4)
  | { type: "reset"; reason: string }   // the speculative data work was for a different scope: clear evidence and hypotheses shown so far
  | { type: "done"; totalMs: number };

export type Emit = (e: ProgressEvent) => void;

/** Wraps a listener so that it can be called without checks and cannot throw into the caller. */
export function safeEmit(listener?: (e: ProgressEvent) => void): Emit {
  return (e) => { try { listener?.(e); } catch { /* a UI listener must never break the investigation */ } };
}

/** Runs `fn` between a "started" and a "finished" event; the elapsed milliseconds are added to `timings[step]`. */
export async function timed<T>(emit: Emit, timings: Record<string, number>, step: StepName, fn: () => Promise<T>): Promise<T> {
  const s = performance.now();
  emit({ type: "step", step, status: "started" });
  try { return await fn(); } finally {
    const ms = Math.round(performance.now() - s);
    timings[step] = (timings[step] ?? 0) + ms;
    emit({ type: "step", step, status: "finished", ms });
  }
}

export const evidenceEvent = (e: Evidence): ProgressEvent => ({ type: "evidence", evidence: { id: e.id, hypothesisId: e.hypothesisId, title: e.title, rowCount: e.rowCount, zetarisRunId: e.zetarisRunId, sources: e.sources } });

export const server = createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", "http://x");
  const p = url.pathname;
  try {
    if (req.method === "GET" && p === "/api/status") {
      const [m, z] = await Promise.all([providerStatus(), zetarisStatus()]);
      return json(res, 200, { zetaris: { ok: z.ok, ms: z.ms, views: 10 }, meterless: m.meterless, fallback: { enabled: !!m.fallback }, lastRoute: m.lastRoute ?? null, busy });
    }
    if (req.method === "POST" && p === "/api/ask") return await ask(req, res);
    if (req.method === "GET" && p === "/api/answers") return json(res, 200, listAnswers());
    let m = p.match(/^\/api\/answers\/([a-z0-9-]+)$/i);
    if (req.method === "GET" && m) { const a = readAnswer(m[1]); return a ? json(res, 200, a) : json(res, 404, { error: "not found" }); }
    m = p.match(/^\/api\/evidence\/([a-z0-9-]+)\/(E\d+)$/i);
    if (req.method === "GET" && m) { const e = readAnswer(m[1])?.evidence?.find((x: any) => x.id === m![2]); return e ? json(res, 200, e) : json(res, 404, { error: "not found" }); }
    if (req.method === "GET" && p === "/api/memory") return json(res, 200, memory.list({ site: url.searchParams.get("site") ?? undefined }));
    m = p.match(/^\/api\/memory\/([^/]+)\/audit$/);
    if (req.method === "GET" && m) return json(res, 200, memory.audit(decodeURIComponent(m[1])));
    if (req.method === "POST" && p === "/api/notes") {
      const { site, text } = await readBody(req);
      if (typeof text !== "string" || !text.trim() || text.length > 1000) return json(res, 400, { error: "text required (≤1000 chars)" });
      const rec = await memory.remember(text.trim(), { source: "user", site: site || undefined });
      return json(res, 201, { id: rec.id });
    }
    if (req.method === "GET" && p === "/api/entities") return json(res, 200, { sites: world.sites(), counts: world.counts() });
    if (p.startsWith("/api/")) return json(res, 404, { error: "unknown endpoint" });
    if (req.method === "GET") return serveStatic(p, res);
    json(res, 405, { error: "method not allowed" });
  } catch (err) { if (!res.headersSent) json(res, 500, { error: String((err as Error)?.message ?? err).slice(0, 300) }); else res.end(); }
});

if (import.meta.url === `file://${process.argv[1]}`) {
  server.listen(PORT, HOST, () => console.log(`Kilowhy on http://${HOST}:${PORT}  (UI + API; meter kWh are SAMPLE data)`));
}

