success.content:
/** Client-side mirrors of server investigation types (web/ only; do not import from server/). */

export type SourceKind =
  | "REST: Octopus"
  | "REST: NESO"
  | "REST: Elexon"
  | "REST: Open-Meteo"
  | "FILE: sample";

export interface EvidenceSource {
  view: string;
  kind: SourceKind;
}

export interface MetricValue {
  value: number | string | boolean | null;
  unit: string;
}

export type Row = Record<string, unknown>;

export interface Evidence {
  id: string;
  hypothesisId: string;
  title: string;
  sql: string;
  zetarisRunId: string;
  rowCount: number;
  resultSha256: string;
  sampleRows: Row[];
  metrics: Record<string, MetricValue>;
  sources: EvidenceSource[];
}

export interface Fact {
  id: string;
  key: string;
  label: string;
  value: number | string | boolean | null;
  unit: string;
  display: string;
  evidence: string;
  hypothesis?: string;
}

export interface AnswerItem {
  text: string;
  facts: string[];
  evidence: string[];
}

export interface RuledOutItem extends AnswerItem {
  hypothesis: string;
}

export interface Answer {
  headline: string;
  sentences: AnswerItem[];
  ruledOut: RuledOutItem[];
  recommendation: AnswerItem;
}

export type HypothesisStatus = "supported" | "ruled_out" | "inconclusive";

export interface HypothesisResult {
  id: string;
  name: string;
  status: HypothesisStatus;
  headline: string;
  summary: Record<string, unknown>;
  evidence: string[];
  notes: string[];
  details?: Record<string, unknown>;
}

export interface DateWindow {
  id: "A" | "B";
  from: string;
  toExclusive: string;
  days: number;
}

export interface ScopeInfo {
  label: string;
  sites: { id: string; name: string }[];
  windowA: DateWindow;
  windowB: DateWindow;
}

export interface DecomposeOk {
  ok: true;
  QA: number;
  QB: number;
  CA: number;
  CB: number;
  pbarA: number;
  pbarB: number;
  pbarBStar: number;
  standingA: number;
  standingB: number;
  totalA: number;
  totalB: number;
  deltaEnergy: number;
  deltaTotal: number;
  volume: number;
  price: number;
  timing: number;
  standing: number;
  identityError: number;
}

export interface DecompositionSummary {
  ok: boolean;
  error?: string;
  result: DecomposeOk | null;
  standing: { A: number; B: number };
  vatRate: number | null;
  evidenceId: string;
  contractEvidenceId: string;
  warnings: string[];
  slotsAligned: number;
  slotsExpected: number;
}

export interface Usage {
  inputTokens: number | null;
  outputTokens: number | null;
  totalTokens: number | null;
  outputTps: number | null;
  routerLatencyMs: number | null;
}

export interface Route {
  provider: "meterless" | "nvidia-direct";
  requestedModel: string;
  routedModel: string | null;
  label: string | null;
  kind: string | null;
  tier: string | null;
  latencyMs: number;
  receiptId: string | null;
  raceWidth: number | null;
  usage: Usage;
  fallbackReason?: string;
  fromCache?: boolean;
}

export interface LlmCall {
  step: string;
  route?: Route;
  error?: string;
  wallMs?: number;
  rejected?: string;
}

export interface Verification {
  passed: boolean;
  attempts: number;
  mode: "llm" | "template";
  errors: string[];
  errorDetail: { part: string; index: number; reason: string }[];
  history: { attempt: number; errors: string[]; repairs: string[] }[];
  repairs: string[];
}

export interface TariffSide {
  energyGbp: number;
  standingGbp: number;
  totalGbp: number;
}

export interface TariffWindow {
  win: "A" | "B";
  slots: number;
  days: number;
  kwh: number;
  agile: TariffSide;
  flat: TariffSide;
  flatMinusAgileGbp: number;
  flatUnitRateRangeP: [number, number];
  coverageComplete: boolean;
}

export interface TariffComparison {
  scope: string;
  ok: boolean;
  reason?: string;
  historicalCounterfactual: true;
  notAdvice: string;
  tariff: {
    productCode: string;
    tariffCode: string;
    name: string;
    region: string;
    why: string;
    vatRate: number | null;
    vatBasis: string;
  };
  windows: { A: TariffWindow; B: TariffWindow } | null;
  sites: { site: string; A: TariffWindow; B: TariffWindow }[];
  cheaperInWindowB: "agile" | "flat" | "equal" | null;
  text: string;
  evidence: string[];
}

export interface Recommendation {
  scope: string;
  ok: boolean;
  reason?: string;
  maxKwhPerDay: number;
  blockSlots: number;
  sites: unknown[];
  total: {
    daysUsed: number;
    daysShifted: number;
    shiftedKwh: number;
    costBeforeGbp: number;
    costAfterGbp: number;
    savedGbp: number;
    savedKgCo2e: number | null;
  };
  text: string;
  evidence: string[];
}

export interface Intent {
  type: string;
  requestedSites: string[];
  dates: string[];
  source: "llm" | "fallback";
}

export interface Plan {
  hypotheses: string[];
  added: string[];
  dropped: string[];
  extraSql: unknown[];
  rationale: string;
  source: "llm" | "default";
}

export interface InvestigationResult {
  question: string;
  intent: Intent;
  scope: ScopeInfo;
  decomposition: DecompositionSummary;
  plan: Plan;
  results: HypothesisResult[];
  evidence: Evidence[];
  facts: Fact[];
  recommendation: { loadShift: Recommendation | null; tariff: TariffComparison | null };
  answer: Answer;
  verification: Verification;
  llmCalls: LlmCall[];
  timings: { total: number; [step: string]: number };
  notes: string[];
  sampleDataNote: string;
  generatedAt?: string;
}

export interface ClarificationResult {
  question: string;
  clarification: string;
  knownSites: { id: string; name: string }[];
  llmCalls: LlmCall[];
  timings: { total: number; [step: string]: number };
}

export type InvestigateOutcome = InvestigationResult | ClarificationResult;

export const isClarification = (o: InvestigateOutcome): o is ClarificationResult =>
  "clarification" in o;

export type StepName =
  | "sites"
  | "intent"
  | "plan"
  | "data"
  | "hypotheses"
  | "recommend"
  | "extraSql"
  | "facts"
  | "narrative"
  | "template";

export type ProgressEvent =
  | { type: "step"; step: StepName; status: "started" | "finished"; ms?: number }
  | {
      type: "evidence";
      evidence: {
        id: string;
        hypothesisId: string;
        title: string;
        rowCount: number;
        zetarisRunId: string;
        sources: EvidenceSource[];
      };
    }
  | { type: "hypothesis"; id: string; name: string; status: string }
  | { type: "llm"; call: LlmCall }
  | { type: "reset"; reason: string }
  | { type: "done"; totalMs: number };

export type MeterlessStatus = "online" | "unauthorized" | "offline";

export interface ApiStatus {
  zetaris: { ok: boolean; views: number };
  meterless: { status: MeterlessStatus; baseUrl: string | null };
  fallback: { enabled: boolean };
  lastRoute?: Route | null;
}

export interface MemoryNote {
  id: string;
  site: string;
  text: string;
  createdAt: string;
  source?: string;
}

export interface AskHandlers {
  onProgress: (event: ProgressEvent) => void;
  onResult: (result: InvestigateOutcome) => void;
  onError: (message: string) => void;
}

import type {
  ApiStatus,
  AskHandlers,
  InvestigateOutcome,
  InvestigationResult,
  MemoryNote,
  ProgressEvent,
  StepName,
} from "../types";

const API = "/api";

async function jsonOrThrow<T>(res: Response): Promise<T> {
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(text || `${res.status} ${res.statusText}`);
  }
  return res.json() as Promise<T>;
}

export async function fetchStatus(): Promise<ApiStatus> {
  const res = await fetch(`${API}/status`);
  return jsonOrThrow<ApiStatus>(res);
}

export async function fetchAnswers(): Promise<{ slug: string; question: string }[]> {
  const res = await fetch(`${API}/answers`);
  return jsonOrThrow(res);
}

export async function fetchAnswer(slug: string): Promise<InvestigationResult> {
  const res = await fetch(`${API}/answers/${encodeURIComponent(slug)}`);
  return jsonOrThrow<InvestigationResult>(res);
}

export async function fetchMemory(site: string): Promise<MemoryNote[]> {
  const res = await fetch(`${API}/memory?site=${encodeURIComponent(site)}`);
  if (res.status === 404) return [];
  return jsonOrThrow<MemoryNote[]>(res);
}

export async function postNote(site: string, text: string): Promise<MemoryNote> {
  const res = await fetch(`${API}/notes`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ site, text }),
  });
  return jsonOrThrow<MemoryNote>(res);
}

export async function fetchAudit(id: string): Promise<unknown> {
  const res = await fetch(`${API}/memory/${encodeURIComponent(id)}/audit`);
  if (res.status === 404) throw new Error("Audit not available yet");
  return jsonOrThrow(res);
}

/** Parse SSE from a POST ReadableStream (not EventSource). */
export async function askQuestion(
  body: { question: string; site?: string },
  handlers: AskHandlers,
  signal?: AbortSignal,
): Promise<void> {
  const res = await fetch(`${API}/ask`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "text/event-stream" },
    body: JSON.stringify(body),
    signal,
  });
  if (!res.ok || !res.body) {
    const text = await res.text().catch(() => "");
    throw new Error(text || `${res.status} ${res.statusText}`);
  }

  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let eventName = "message";
  let dataLines: string[] = [];

  const flush = () => {
    if (dataLines.length === 0) {
      eventName = "message";
      return;
    }
    const raw = dataLines.join("\n");
    dataLines = [];
    const name = eventName;
    eventName = "message";
    try {
      const payload = JSON.parse(raw) as unknown;
      if (name === "progress") handlers.onProgress(payload as ProgressEvent);
      else if (name === "result") handlers.onResult(payload as InvestigateOutcome);
      else if (name === "error") {
        const msg =
          typeof payload === "string"
            ? payload
            : (payload as { message?: string }).message ?? "Investigation failed";
        handlers.onError(msg);
      }
    } catch {
      handlers.onError(`Could not parse SSE ${name} payload`);
    }
  };

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const parts = buffer.split(/\r?\n/);
    buffer = parts.pop() ?? "";
    for (const line of parts) {
      if (line === "") {
        flush();
        continue;
      }
      if (line.startsWith(":")) continue;
      if (line.startsWith("event:")) {
        eventName = line.slice(6).trim();
      } else if (line.startsWith("data:")) {
        dataLines.push(line.slice(5).replace(/^ /, ""));
      }
    }
  }
  flush();
}

/** Simulate progress events when serving a fixture offline. */
export function simulateProgress(
  result: InvestigationResult,
  onProgress: (e: ProgressEvent) => void,
): Promise<void> {
  const steps: StepName[] = [
    "intent",
    "plan",
    "data",
    "hypotheses",
    "recommend",
    "facts",
    "narrative",
  ];
  return new Promise((resolve) => {
    let i = 0;
    const tick = () => {
      if (i < steps.length) {
        const step = steps[i];
        onProgress({ type: "step", step, status: "started" });
        if (step === "data" || step === "hypotheses") {
          const chunk = result.evidence.slice(
            step === "data" ? 0 : Math.min(3, result.evidence.length),
            step === "data" ? Math.min(3, result.evidence.length) : result.evidence.length,
          );
          for (const e of chunk) {
            onProgress({
              type: "evidence",
              evidence: {
                id: e.id,
                hypothesisId: e.hypothesisId,
                title: e.title,
                rowCount: e.rowCount,
                zetarisRunId: e.zetarisRunId,
                sources: e.sources,
              },
            });
          }
        }
        if (step === "hypotheses") {
          for (const h of result.results) {
            onProgress({ type: "hypothesis", id: h.id, name: h.name, status: h.status });
          }
        }
        if (step === "intent" || step === "plan" || step === "narrative") {
          const call = result.llmCalls.find((c) => c.step === step) ?? result.llmCalls[0];
          if (call) onProgress({ type: "llm", call });
        }
        onProgress({ type: "step", step, status: "finished", ms: result.timings[step] ?? 120 });
        i += 1;
        setTimeout(tick, 180);
        return;
      }
      onProgress({ type: "done", totalMs: result.timings.total ?? 0 });
      resolve();
    };
    tick();
  });
}

import type { Fact, DecompositionSummary } from "../types";
import { factDisplay } from "../format";

interface Props {
  decomposition: DecompositionSummary;
  facts: Fact[];
}

interface Bar {
  key: string;
  label: string;
  display: string;
  /** Signed GBP for geometry only (from decomposition pence / 100, or fact value). */
  gbp: number;
  kind: "total" | "up" | "down" | "zero";
}

function penceToGbp(p: number): number {
  return p / 100;
}

export function Waterfall({ decomposition, facts }: Props) {
  const r = decomposition.result;
  if (!r) return null;

  const billA = factDisplay(facts, "bill_A") ?? `£${penceToGbp(r.totalA).toFixed(2)}`;
  const billB = factDisplay(facts, "bill_B") ?? `£${penceToGbp(r.totalB).toFixed(2)}`;
  const standing = factDisplay(facts, "S") ?? `£${penceToGbp(r.standing).toFixed(2)}`;
  const weather = factDisplay(facts, "v_weather");
  const operational = factDisplay(facts, "v_operational");
  const volume = factDisplay(facts, "V") ?? `£${penceToGbp(r.volume).toFixed(2)}`;
  const price = factDisplay(facts, "L") ?? `£${penceToGbp(r.price).toFixed(2)}`;
  const timing = factDisplay(facts, "T") ?? `£${penceToGbp(r.timing).toFixed(2)}`;

  const weatherGbp =
    typeof facts.find((f) => f.key === "v_weather")?.value === "number"
      ? (facts.find((f) => f.key === "v_weather")!.value as number)
      : penceToGbp(r.volume) * 0.8;
  const opsGbp =
    typeof facts.find((f) => f.key === "v_operational")?.value === "number"
      ? (facts.find((f) => f.key === "v_operational")!.value as number)
      : penceToGbp(r.volume) - weatherGbp;

  const bars: Bar[] = [
    { key: "A", label: "Window A", display: billA, gbp: penceToGbp(r.totalA), kind: "total" },
    {
      key: "S",
      label: "Standing",
      display: standing,
      gbp: penceToGbp(r.standing),
      kind: r.standing === 0 ? "zero" : r.standing > 0 ? "up" : "down",
    },
    {
      key: "Vw",
      label: "Weather volume",
      display: weather ?? volume,
      gbp: weather ? weatherGbp : penceToGbp(r.volume),
      kind: (weather ? weatherGbp : r.volume) === 0 ? "zero" : (weather ? weatherGbp : r.volume) > 0 ? "up" : "down",
    },
    ...(weather
      ? [
          {
            key: "Vo",
            label: "Operational volume",
            display: operational ?? "£0.00",
            gbp: opsGbp,
            kind: (opsGbp === 0 ? "zero" : opsGbp > 0 ? "up" : "down") as Bar["kind"],
          },
        ]
      : []),
    {
      key: "L",
      label: "Price",
      display: price,
      gbp: penceToGbp(r.price),
      kind: r.price === 0 ? "zero" : r.price > 0 ? "up" : "down",
    },
    {
      key: "T",
      label: "Timing",
      display: timing,
      gbp: penceToGbp(r.timing),
      kind: r.timing === 0 ? "zero" : r.timing > 0 ? "up" : "down",
    },
    { key: "B", label: "Window B", display: billB, gbp: penceToGbp(r.totalB), kind: "total" },
  ];

  const W = 640;
  const H = 220;
  const padL = 8;
  const padR = 8;
  const padT = 28;
  const padB = 48;
  const gap = 10;
  const n = bars.length;
  const barW = (W - padL - padR - gap * (n - 1)) / n;

  // Running level for floating bars (bridge chart)
  let level = 0;
  const levels: number[] = [];
  for (const b of bars) {
    if (b.kind === "total") {
      levels.push(0);
      level = b.gbp;
    } else {
      const start = b.gbp >= 0 ? level : level + b.gbp;
      levels.push(start);
      level += b.gbp;
    }
  }

  const values = bars.flatMap((b, i) =>
    b.kind === "total" ? [b.gbp] : [levels[i], levels[i] + Math.abs(b.gbp)],
  );
  const minY = Math.min(0, ...values) * 0.98;
  const maxY = Math.max(...values) * 1.02;
  const span = maxY - minY || 1;
  const yScale = (v: number) => padT + ((maxY - v) / span) * (H - padT - padB);
  const hScale = (v: number) => (Math.abs(v) / span) * (H - padT - padB);

  return (
    <figure className="waterfall">
      <figcaption>How the bill moved (window A → window B)</figcaption>
      <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Bill change waterfall">
        {bars.map((b, i) => {
          const x = padL + i * (barW + gap);
          const isTotal = b.kind === "total";
          const top = isTotal ? yScale(Math.max(b.gbp, 0)) : yScale(levels[i] + Math.max(b.gbp, 0));
          const height = Math.max(hScale(isTotal ? b.gbp : b.gbp), 2);
          const fill =
            b.kind === "total"
              ? "var(--wf-total)"
              : b.kind === "up"
                ? "var(--wf-up)"
                : b.kind === "down"
                  ? "var(--wf-down)"
                  : "var(--wf-zero)";
          return (
            <g key={b.key}>
              <rect x={x} y={top} width={barW} height={height} rx={3} fill={fill} />
              <text
                x={x + barW / 2}
                y={top - 6}
                textAnchor="middle"
                className="wf-value"
              >
                {b.display}
              </text>
              <text
                x={x + barW / 2}
                y={H - 18}
                textAnchor="middle"
                className="wf-label"
              >
                {b.label}
              </text>
            </g>
          );
        })}
        {/* connector lines between floating bars */}
        {bars.map((b, i) => {
          if (i === 0 || b.kind === "total") return null;
          const prev = bars[i - 1];
          const x0 = padL + (i - 1) * (barW + gap) + barW;
          const x1 = padL + i * (barW + gap);
          const y =
            prev.kind === "total"
              ? yScale(prev.gbp)
              : yScale(levels[i - 1] + Math.max(prev.gbp, 0));
          return (
            <line
              key={`c-${b.key}`}
              x1={x0}
              x2={x1}
              y1={y}
              y2={y}
              className="wf-connector"
            />
          );
        })}
      </svg>
    </figure>
  );
}

import { useCallback, useEffect, useState, type FormEvent } from "react";
import { fetchAudit, fetchMemory, postNote } from "../api/client";
import type { MemoryNote } from "../types";

interface Props {
  site: string;
  apiOnline: boolean;
  focusId?: string | null;
}

export function MemoryPanel({ site, apiOnline, focusId }: Props) {
  const [open, setOpen] = useState(false);
  const [notes, setNotes] = useState<MemoryNote[]>([]);
  const [text, setText] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [audit, setAudit] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    if (!apiOnline) {
      setNotes([]);
      setError("Memory API unavailable offline");
      return;
    }
    try {
      setError(null);
      const list = await fetchMemory(site === "ALL" ? "" : site);
      setNotes(Array.isArray(list) ? list : []);
    } catch {
      setNotes([]);
      setError("Memory not available yet (endpoint may 404).");
    }
  }, [apiOnline, site]);

  useEffect(() => {
    if (open) void load();
  }, [open, load]);

  useEffect(() => {
    if (focusId) setOpen(true);
  }, [focusId]);

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    if (!text.trim() || !apiOnline) return;
    setBusy(true);
    try {
      await postNote(site === "ALL" ? "ALL" : site, text.trim());
      setText("");
      await load();
    } catch {
      setError("Could not save note.");
    } finally {
      setBusy(false);
    }
  };

  const showAudit = async (id: string) => {
    try {
      const data = await fetchAudit(id);
      setAudit(JSON.stringify(data, null, 2));
    } catch {
      setAudit("Audit trail not available yet.");
    }
  };

  return (
    <section className="memory-panel">
      <button type="button" className="memory-toggle" onClick={() => setOpen((v) => !v)}>
        {open ? "Hide memory" : "Show memory"} — notes about sites
      </button>
      {open && (
        <div className="memory-body">
          {error && <p className="muted small">{error}</p>}
          <ul className="memory-list">
            {notes.length === 0 && !error && <li className="muted">No notes yet.</li>}
            {notes.map((n) => (
              <li key={n.id} className={focusId === n.id ? "focus" : ""}>
                <div className="note-meta">
                  <time dateTime={n.createdAt}>
                    {n.createdAt ? new Date(n.createdAt).toLocaleString() : "—"}
                  </time>
                  <span>{n.site}</span>
                  {n.source && <span>{n.source}</span>}
                  <button type="button" className="text-btn" onClick={() => void showAudit(n.id)}>
                    Audit trail
                  </button>
                </div>
                <p>{n.text}</p>
              </li>
            ))}
          </ul>
          <form className="note-form" onSubmit={(e) => void submit(e)}>
            <label htmlFor="note-text">Add a note</label>
            <textarea
              id="note-text"
              rows={3}
              value={text}
              disabled={!apiOnline || busy}
              onChange={(e) => setText(e.target.value)}
              placeholder="e.g. Freezer at Hampstead was repaired on 12 Oct"
            />
            <button type="submit" disabled={!apiOnline || busy || !text.trim()}>
              Save note
            </button>
          </form>
          {audit && (
            <pre className="audit-pre">
              <code>{audit}</code>
            </pre>
          )}
        </div>
      )}
    </section>
  );
}

import type { EvidenceSource, LlmCall, ProgressEvent, StepName } from "../types";
import { formatRoute, sourceBadges, stepLabel } from "../format";

export interface TimelineEvidence {
  id: string;
  title: string;
  sources: EvidenceSource[];
  rowCount: number;
}

export interface TimelineState {
  steps: Partial<Record<StepName, { status: "started" | "finished"; ms?: number }>>;
  evidence: TimelineEvidence[];
  hypotheses: { id: string; name: string; status: string }[];
  llmCalls: LlmCall[];
  doneMs?: number;
  resetReason?: string;
}

export function emptyTimeline(): TimelineState {
  return { steps: {}, evidence: [], hypotheses: [], llmCalls: [] };
}

export function reduceTimeline(state: TimelineState, event: ProgressEvent): TimelineState {
  switch (event.type) {
    case "reset":
      return { ...emptyTimeline(), resetReason: event.reason };
    case "step":
      return {
        ...state,
        steps: {
          ...state.steps,
          [event.step]: { status: event.status, ms: event.ms },
        },
      };
    case "evidence":
      if (state.evidence.some((e) => e.id === event.evidence.id)) return state;
      return {
        ...state,
        evidence: [
          ...state.evidence,
          {
            id: event.evidence.id,
            title: event.evidence.title,
            sources: event.evidence.sources,
            rowCount: event.evidence.rowCount,
          },
        ],
      };
    case "hypothesis":
      return {
        ...state,
        hypotheses: [
          ...state.hypotheses.filter((h) => h.id !== event.id),
          { id: event.id, name: event.name, status: event.status },
        ],
      };
    case "llm":
      return { ...state, llmCalls: [...state.llmCalls, event.call] };
    case "done":
      return { ...state, doneMs: event.totalMs };
    default:
      return state;
  }
}

const STAGE_ORDER: { label: string; steps: StepName[] }[] = [
  { label: "Understand question", steps: ["sites", "intent", "plan"] },
  { label: "Split the bill", steps: ["data"] },
  { label: "Test hypotheses", steps: ["hypotheses", "extraSql", "recommend"] },
  { label: "Write answer", steps: ["facts", "narrative", "template"] },
  { label: "Verify every figure", steps: ["narrative", "template"] },
];

interface Props {
  state: TimelineState;
  visible: boolean;
  onOpenEvidence: (id: string) => void;
}

export function Timeline({ state, visible, onOpenEvidence }: Props) {
  if (!visible) return null;

  return (
    <section className="timeline" aria-live="polite" aria-label="Live investigation">
      <h2>Investigation</h2>
      {state.resetReason && (
        <p className="timeline-reset">Scope changed — restarting evidence ({state.resetReason})</p>
      )}
      <ol className="timeline-stages">
        {STAGE_ORDER.map((stage) => {
          const statuses = stage.steps.map((s) => state.steps[s]?.status);
          const active = statuses.includes("started");
          const done = stage.steps.some((s) => state.steps[s]?.status === "finished");
          const ms = stage.steps.reduce((a, s) => a + (state.steps[s]?.ms ?? 0), 0);
          return (
            <li key={stage.label} className={`stage ${active ? "active" : ""} ${done ? "done" : ""}`}>
              <span className="stage-dot" aria-hidden />
              <span className="stage-label">{stage.label}</span>
              {done && ms > 0 && <span className="stage-ms">{(ms / 1000).toFixed(1)} s</span>}
            </li>
          );
        })}
      </ol>

      {state.llmCalls.length > 0 && (
        <ul className="llm-routes">
          {state.llmCalls.map((call, i) => (
            <li key={`${call.step}-${i}`} className={call.route?.provider === "nvidia-direct" ? "fallback" : ""}>
              <span className="llm-step">{stepLabel(call.step)}</span>
              {call.route ? (
                <span className="llm-route">{formatRoute(call.route)}</span>
              ) : (
                <span className="llm-route error">{call.error ?? "no route"}</span>
              )}
            </li>
          ))}
        </ul>
      )}

      {state.evidence.length > 0 && (
        <div className="evidence-stream">
          <h3>Evidence gathered</h3>
          <ul>
            {state.evidence.map((e) => (
              <li key={e.id}>
                <button type="button" className="evidence-pill" onClick={() => onOpenEvidence(e.id)}>
                  <strong>{e.id}</strong>
                  <span className="ev-title">{e.title}</span>
                  <span className="ev-badges">
                    {sourceBadges(e.sources).map((b) => (
                      <span key={b} className="src-badge">
                        {b}
                      </span>
                    ))}
                  </span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}

      {state.doneMs != null && (
        <p className="timeline-done">Finished in {(state.doneMs / 1000).toFixed(1)} s</p>
      )}
    </section>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { askQuestion, fetchStatus, simulateProgress } from "./api/client";
import { AnswerCard } from "./components/AnswerCard";
import { EvidenceDrawer } from "./components/EvidenceDrawer";
import { Header } from "./components/Header";
import { HowItWorks } from "./components/HowItWorks";
import { MemoryPanel } from "./components/MemoryPanel";
import { OfflineNotice } from "./components/OfflineNotice";
import { QuestionBox } from "./components/QuestionBox";
import { RecommendationCard } from "./components/RecommendationCard";
import { RuledOut } from "./components/RuledOut";
import {
  emptyTimeline,
  reduceTimeline,
  Timeline,
  type TimelineState,
} from "./components/Timeline";
import { FIXTURES, matchFixture, sitesFromFixtures, SUGGESTED_QUESTIONS } from "./fixtures";
import type { ApiStatus, Evidence, InvestigateOutcome, InvestigationResult } from "./types";
import { isClarification } from "./types";

type Theme = "light" | "dark";

function preferTheme(): Theme {
  if (typeof window === "undefined") return "light";
  return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
}

export default function App() {
  const [theme, setTheme] = useState<Theme>(preferTheme);
  const [status, setStatus] = useState<ApiStatus | null>(null);
  const [apiOnline, setApiOnline] = useState(false);
  const [offlineDemo, setOfflineDemo] = useState(false);

  const [question, setQuestion] = useState(SUGGESTED_QUESTIONS[0]);
  const [site, setSite] = useState("ALL");
  const sites = useMemo(() => sitesFromFixtures(), []);

  const [busy, setBusy] = useState(false);
  const [timeline, setTimeline] = useState<TimelineState>(emptyTimeline());
  const [result, setResult] = useState<InvestigationResult | null>(null);
  const [clarification, setClarification] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [drawerId, setDrawerId] = useState<string | null>(null);
  const [memoryFocus, setMemoryFocus] = useState<string | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  useEffect(() => {
    document.documentElement.dataset.theme = theme;
  }, [theme]);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const s = await fetchStatus();
        if (cancelled) return;
        setStatus(s);
        setApiOnline(true);
        setOfflineDemo(false);
      } catch {
        if (cancelled) return;
        setApiOnline(false);
        setOfflineDemo(true);
        setStatus({
          zetaris: { ok: false, views: 0 },
          meterless: { status: "offline", baseUrl: null },
          fallback: { enabled: true },
        });
        // Seed first fixture so the page isn't empty offline
        setResult(FIXTURES[0].result);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const evidenceMap = useMemo(() => {
    const m = new Map<string, Evidence>();
    if (result) for (const e of result.evidence) m.set(e.id, e);
    return m;
  }, [result]);

  const openEvidence = useCallback((id: string) => setDrawerId(id), []);

  const applyOutcome = useCallback((outcome: InvestigateOutcome) => {
    if (isClarification(outcome)) {
      setClarification(outcome.clarification);
      setResult(null);
    } else {
      setClarification(null);
      setResult(outcome);
    }
  }, []);

  const runOffline = useCallback(
    async (q: string, siteId: string) => {
      const fixture = matchFixture(q, siteId);
      if (!fixture) {
        setError("No offline fixture matches this question.");
        return;
      }
      setOfflineDemo(true);
      setTimeline(emptyTimeline());
      await simulateProgress(fixture, (ev) => setTimeline((t) => reduceTimeline(t, ev)));
      applyOutcome(fixture);
    },
    [applyOutcome],
  );

  const onAsk = useCallback(async () => {
    const q = question.trim();
    if (!q || busy) return;
    abortRef.current?.abort();
    const ac = new AbortController();
    abortRef.current = ac;

    setBusy(true);
    setError(null);
    setClarification(null);
    setTimeline(emptyTimeline());
    setDrawerId(null);

    try {
      if (!apiOnline) {
        await runOffline(q, site);
        return;
      }
      let gotResult = false;
      await askQuestion(
        { question: q, site: site === "ALL" ? undefined : site },
        {
          onProgress: (ev) => setTimeline((t) => reduceTimeline(t, ev)),
          onResult: (outcome) => {
            gotResult = true;
            applyOutcome(outcome);
          },
          onError: (msg) => setError(msg),
        },
        ac.signal,
      );
      if (!gotResult && !ac.signal.aborted) {
        // Stream ended without a result — fall back
        await runOffline(q, site);
      }
    } catch (err) {
      if ((err as Error).name === "AbortError") return;
      setApiOnline(false);
      await runOffline(q, site);
    } finally {
      setBusy(false);
    }
  }, [apiOnline, applyOutcome, busy, question, runOffline, site]);

  const drawerEvidence = drawerId ? evidenceMap.get(drawerId) ?? null : null;

  return (
    <div className="app">
      <div className="top-bar">
        <Header status={status} offline={offlineDemo} />
        <button
          type="button"
          className="theme-toggle"
          onClick={() => setTheme((t) => (t === "light" ? "dark" : "light"))}
          aria-label="Toggle light and dark"
        >
          {theme === "light" ? "Dark" : "Light"}
        </button>
      </div>

      <main className="main">
        <OfflineNotice show={offlineDemo} />
        <QuestionBox
          question={question}
          site={site}
          sites={sites}
          busy={busy}
          onQuestion={setQuestion}
          onSite={setSite}
          onAsk={() => void onAsk()}
        />

        <Timeline
          state={timeline}
          visible={busy || timeline.evidence.length > 0 || timeline.llmCalls.length > 0}
          onOpenEvidence={openEvidence}
        />

        {error && (
          <p className="error-banner" role="alert">
            {error}
          </p>
        )}

        {clarification && (
          <section className="clarify">
            <h2>Need a bit more detail</h2>
            <p>{clarification}</p>
          </section>
        )}

        {result && (
          <>
            <AnswerCard result={result} onEvidence={openEvidence} onMemory={setMemoryFocus} />
            <RuledOut items={result.answer.ruledOut} onEvidence={openEvidence} />
            <RecommendationCard result={result} onEvidence={openEvidence} />
          </>
        )}

        <MemoryPanel site={site} apiOnline={apiOnline} focusId={memoryFocus} />
      </main>

      <HowItWorks />

      <EvidenceDrawer
        evidence={drawerEvidence}
        open={!!drawerEvidence}
        onClose={() => setDrawerId(null)}
      />
    </div>
  );
}

