    hypotheses: "Test hypotheses",
    recommend: "Compare tariffs & load shift",
    extraSql: "Extra queries",
    facts: "Collect figures",
    narrative: "Write answer",
    template: "Template answer",
  };
  return map[step] ?? step;
}

