interface AnswerMeta {
  slug: string;
  question: string;
  headline?: string;
  generatedAt?: string;
}

interface Props {
  answers: AnswerMeta[];
  busy: boolean;
  onOpen: (slug: string) => void;
  activeSlug?: string | null;
}

export function RecentAnswers({ answers, busy, onOpen, activeSlug }: Props) {
