:root,
[data-theme="light"] {
  --bg: #eef2f4;
  --bg-elev: #ffffff;
  --bg-soft: #e4eaee;
  --ink: #152028;
  --ink-muted: #5a6874;
  --accent: #0d6b5c;
  --accent-soft: #d5ebe5;
  --warn: #9a4d1c;
  --danger: #9b2c2c;
  --border: #c9d3da;
  --chip: #e2e8ec;
  --shadow: 0 1px 0 rgba(21, 32, 40, 0.05), 0 14px 36px rgba(21, 32, 40, 0.07);
  --wf-total: #152028;
  --wf-up: #c45c26;
  --wf-down: #0d6b5c;
  --wf-zero: #8a959e;
  --drawer-w: min(440px, 100vw);
  --font-display: "Fraunces", "Georgia", serif;
  --font-body: "Source Sans 3", "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;
  color-scheme: light;
}

[data-theme="dark"] {
  --bg: #10161a;
  --bg-elev: #182026;
  --bg-soft: #222c34;
  --ink: #e8eef2;
  --ink-muted: #9aabb8;
  --accent: #5fc4ae;
  --accent-soft: #1d3530;
  --warn: #e0a06a;
  --danger: #e09090;
  --border: #2e3a44;
  --chip: #243038;
  --shadow: 0 1px 0 rgba(0, 0, 0, 0.4), 0 16px 40px rgba(0, 0, 0, 0.4);
  --wf-total: #e8eef2;
  --wf-up: #e0a06a;
  --wf-down: #5fc4ae;
  --wf-zero: #6a7884;
  color-scheme: dark;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  font-size: 17px;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: var(--font-body);
  background:
    radial-gradient(ellipse 80% 50% at 10% -10%, color-mix(in srgb, var(--accent) 12%, transparent), transparent),
    radial-gradient(ellipse 60% 40% at 100% 0%, color-mix(in srgb, var(--warn) 8%, transparent), transparent),
    var(--bg);
  color: var(--ink);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

button,
textarea,
select,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

code,
pre {
  font-family: var(--font-mono);
  font-size: 0.85em;
}

.app {
  max-width: 920px;
  margin: 0 auto;
  padding: 1.25rem 1.1rem 3rem;
}

.top-bar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.theme-toggle {
  flex-shrink: 0;
  border: 1px solid var(--border);
  background: var(--bg-elev);
  border-radius: 999px;
  padding: 0.35rem 0.85rem;
  font-size: 0.85rem;
  color: var(--ink-muted);
}

.site-header {
  flex: 1;
  min-width: 0;
}

.wordmark {
  font-family: var(--font-display);
  font-weight: 650;
  font-size: clamp(2rem, 5vw, 2.6rem);
  letter-spacing: -0.02em;
  margin: 0 0 0.35rem;
  line-height: 1.1;
}

.tagline {
  margin: 0 0 0.9rem;
  color: var(--ink-muted);
  max-width: 36rem;
  font-size: 1.02rem;
}

.status-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.28rem 0.7rem;
  border-radius: 999px;
  background: var(--chip);
  font-size: 0.78rem;
  font-weight: 500;
  border: 1px solid transparent;
}

.chip.ok {
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border));
  background: var(--accent-soft);
}

.chip.warn {
  border-color: color-mix(in srgb, var(--warn) 40%, var(--border));
}

.offline-notice {
  margin: 0 0 1rem;
  padding: 0.55rem 0.85rem;
  border-radius: 8px;
  background: color-mix(in srgb, var(--warn) 14%, var(--bg-elev));
  border: 1px solid color-mix(in srgb, var(--warn) 35%, var(--border));
  color: var(--warn);
  font-size: 0.9rem;
}

.main {
  display: flex;
  flex-direction: column;
  gap: 1.35rem;
}

.question-box,
.timeline,
.answer-card,
.ruled-out,
.rec-card,
.clarify,
.memory-panel {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.1rem 1.2rem 1.25rem;
  box-shadow: var(--shadow);
}

.question-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.5rem;
}

.question-head label {
  font-weight: 600;
}

.sample-badge {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 0.2rem 0.55rem;
  border-radius: 4px;
  background: var(--bg-soft);
  border: 1px dashed var(--border);
  color: var(--ink-muted);
}

.question-box textarea {
  width: 100%;
  resize: vertical;
  min-height: 4.5rem;
  padding: 0.75rem 0.85rem;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--bg);
  outline: none;
}

.question-box textarea:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 22%, transparent);
}

.question-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: flex-end;
  margin-top: 0.75rem;
}

.site-select {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.85rem;
  color: var(--ink-muted);
  flex: 1;
  min-width: 160px;
}

.site-select select {
  padding: 0.55rem 0.7rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg);
}

.ask-btn {
  border: none;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  padding: 0.65rem 1.25rem;
  border-radius: 999px;
  min-height: 2.6rem;
}

[data-theme="dark"] .ask-btn {
  color: #10241c;
}

.ask-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.suggestions {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin-top: 0.9rem;
}

.suggestion {
  text-align: left;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.55rem 0.75rem;
  color: var(--ink-muted);
  font-size: 0.92rem;
}

.suggestion:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--ink);
}

.timeline h2,
.answer-card h2,
.ruled-out h2,
.rec-card h2,
.how-it-works h2,
.clarify h2 {
  font-family: var(--font-display);
  font-weight: 650;
  font-size: 1.35rem;
  margin: 0 0 0.75rem;
}

.timeline-stages {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.45rem;
}

.stage {
  display: grid;
  grid-template-columns: 14px 1fr auto;
  gap: 0.55rem;
  align-items: center;
  color: var(--ink-muted);
  font-size: 0.95rem;
}

.stage-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
}

.stage.active .stage-dot {
  background: var(--accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 25%, transparent);
}

.stage.done {
  color: var(--ink);
}

.stage.done .stage-dot {
  background: var(--accent);
}

.stage-ms {
  font-family: var(--font-mono);
  font-size: 0.78rem;
}

.llm-routes {
  list-style: none;
  margin: 1rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.4rem;
}

.llm-routes li {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 0.85rem;
  padding: 0.5rem 0.65rem;
  background: var(--bg-soft);
  border-radius: 8px;
  font-size: 0.88rem;
}

.llm-routes li.fallback {
  border: 1px solid color-mix(in srgb, var(--warn) 45%, var(--border));
}

