  font-weight: 600;
}

.llm-route {
  color: var(--ink-muted);
}

.llm-route.error {
  color: var(--danger);
}

.evidence-stream {
  margin-top: 1rem;
}

.evidence-stream h3 {
  margin: 0 0 0.5rem;
  font-size: 0.9rem;
  color: var(--ink-muted);
  font-weight: 600;
}

.evidence-stream ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.4rem;
}

.evidence-pill {
  width: 100%;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.35rem 0.65rem;
  text-align: left;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.55rem 0.7rem;
}

.ev-title {
  flex: 1;
  min-width: 10rem;
}

.ev-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.src-badge {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 0.15rem 0.45rem;
  border-radius: 4px;
  background: var(--chip);
  color: var(--ink-muted);
  white-space: nowrap;
}

.src-badge.muted {
  opacity: 0.75;
}

.timeline-done,
.timeline-reset {
  margin: 0.85rem 0 0;
  font-size: 0.9rem;
  color: var(--ink-muted);
}

.answer-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.5rem;
}

.answer-head h2 {
  margin: 0;
  flex: 1;
  min-width: 12rem;
}

.verify-badge {
  font-size: 0.78rem;
  font-weight: 600;
  padding: 0.35rem 0.7rem;
  border-radius: 999px;
  white-space: normal;
  max-width: 16rem;
  line-height: 1.3;
}

.verify-badge.ok {
  background: var(--accent-soft);
  color: var(--accent);
}

.verify-badge.template {
  background: var(--chip);
  color: var(--ink-muted);
}

.verify-badge.warn {
  background: color-mix(in srgb, var(--warn) 18%, transparent);
  color: var(--warn);
}

.waterfall {
  margin: 0.75rem 0 1rem;
}

.waterfall figcaption {
  font-size: 0.85rem;
  color: var(--ink-muted);
  margin-bottom: 0.35rem;
}

.waterfall svg {
  width: 100%;
  height: auto;
  display: block;
  background: var(--bg);
  border-radius: 10px;
  border: 1px solid var(--border);
}

.wf-value {
  fill: var(--ink);
  font-size: 11px;
  font-family: var(--font-mono);
}

.wf-label {
  fill: var(--ink-muted);
  font-size: 10px;
  font-family: var(--font-body);
}

.wf-connector {
  stroke: var(--border);
  stroke-dasharray: 3 3;
  stroke-width: 1;
}

.answer-body {
  display: grid;
  gap: 0.75rem;
}

.sentence {
  margin: 0;
}

.cite {
  display: inline-flex;
  align-items: center;
  margin: 0 0.15rem;
  padding: 0.05rem 0.4rem;
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: 0.78em;
  font-weight: 500;
  border: 1px solid var(--border);
  background: var(--bg-soft);
  vertical-align: baseline;
  line-height: 1.4;
}

button.cite {
  cursor: pointer;
}

.cite-e {
  border-color: color-mix(in srgb, var(--accent) 40%, var(--border));
  color: var(--accent);
}

.cite-f {
  cursor: help;
}

.cite-m {
  border-color: color-mix(in srgb, var(--warn) 40%, var(--border));
}

.cite-trail {
  display: inline;
  margin-left: 0.25rem;
}

.sample-note {
  margin: 1rem 0 0;
  font-size: 0.82rem;
  color: var(--ink-muted);
}

.ruled-chips {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.45rem;
}

.ruled-chip {
  width: 100%;
  text-align: left;
  display: grid;
  gap: 0.25rem;
  padding: 0.65rem 0.8rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg-soft);
  color: var(--ink-muted);
}

.ruled-hyp {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 600;
}

.ruled-text {
  font-size: 0.92rem;
  color: var(--ink);
}

.rec-card h3 {
  font-size: 1rem;
  margin: 1rem 0 0.4rem;
}

.muted {
  color: var(--ink-muted);
}

.small {
  font-size: 0.85rem;
}

.tariff-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.92rem;
  margin: 0.5rem 0;
}

.tariff-table th,
.tariff-table td {
  text-align: left;
  padding: 0.45rem 0.5rem;
  border-bottom: 1px solid var(--border);
}

.tariff-table th {
  color: var(--ink-muted);
  font-weight: 600;
  font-size: 0.8rem;
}

.error-banner {
  margin: 0;
  padding: 0.7rem 0.9rem;
  border-radius: 8px;
  background: color-mix(in srgb, var(--danger) 12%, var(--bg-elev));
  border: 1px solid color-mix(in srgb, var(--danger) 35%, var(--border));
  color: var(--danger);
}

.memory-toggle {
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  font-weight: 600;
  padding: 0;
  color: var(--ink);
}

.memory-body {
  margin-top: 0.85rem;
  display: grid;
  gap: 0.85rem;
}

.memory-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.65rem;
}

.memory-list li {
  padding: 0.65rem 0.75rem;
  border-radius: 8px;
  background: var(--bg);
  border: 1px solid var(--border);
}

.memory-list li.focus {
  border-color: var(--accent);
}

.note-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 0.85rem;
  font-size: 0.78rem;
  color: var(--ink-muted);
  margin-bottom: 0.35rem;
}

.note-form {
  display: grid;
  gap: 0.4rem;
}

.note-form textarea {
  width: 100%;
  padding: 0.6rem 0.7rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg);
  resize: vertical;
}

.note-form button,
.text-btn,
.icon-btn {
  border: 1px solid var(--border);
  background: var(--bg-soft);
  border-radius: 8px;
  padding: 0.45rem 0.8rem;
}

.text-btn {
  background: transparent;
  border: none;
  padding: 0;
  color: var(--accent);
  font-size: inherit;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.audit-pre {
  margin: 0;
  padding: 0.75rem;
  background: var(--bg);
  border-radius: 8px;
  overflow: auto;
  max-height: 12rem;
  font-size: 0.8rem;
}

.how-it-works {
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
}

.pipeline {
  width: 100%;
  height: auto;
  display: block;
  margin: 0.5rem 0 1rem;
}

.pipe-box {
  fill: var(--bg-elev);
  stroke: var(--border);
  stroke-width: 1.5;
}

.pipe-box.accent {
  fill: var(--accent-soft);
}

.pipe-title {
  fill: var(--ink);
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 650;
}

.pipe-line {
  fill: var(--ink-muted);
  font-family: var(--font-body);
  font-size: 11px;
}

.pipe-line.muted {
  fill: var(--ink-muted);
  font-size: 10px;
}

.pipe-arrow {
  stroke: var(--ink-muted);
  stroke-width: 1.5;
}

.built-with {
  font-size: 0.88rem;
  color: var(--ink-muted);
  margin: 0;
}

/* Evidence drawer */
.drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(20, 16, 12, 0.35);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
  z-index: 40;
}

.drawer-backdrop.show {
  opacity: 1;
  pointer-events: auto;
}

.evidence-drawer {
  position: fixed;
  top: 0;
  right: 0;
  width: var(--drawer-w);
  height: 100vh;
  background: var(--bg-elev);
  border-left: 1px solid var(--border);
  box-shadow: var(--shadow);
  z-index: 50;
  transform: translateX(105%);
  transition: transform 0.25s ease;
  overflow: auto;
  padding: 1.1rem 1.15rem 2rem;
}

.evidence-drawer.open {
  transform: translateX(0);
}

.drawer-head {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  align-items: flex-start;
}

.drawer-id {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--accent);
  font-weight: 600;
}

.drawer-head h2 {
  margin: 0.15rem 0 0;
  font-family: var(--font-display);
  font-size: 1.2rem;
}

.icon-btn {
  font-size: 1.4rem;
  line-height: 1;
  width: 2.2rem;
  height: 2.2rem;
  padding: 0;
  flex-shrink: 0;
}

.drawer-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin: 0.85rem 0;
}

.drawer-meta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.65rem;
  margin-bottom: 1rem;
  font-size: 0.88rem;
}

.meta-label {
  display: block;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ink-muted);
  margin-bottom: 0.15rem;
}

.sql-block {
  margin-bottom: 1rem;
}

.sql-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.35rem;
  font-size: 0.85rem;
  color: var(--ink-muted);
}

.sql-block pre {
  margin: 0;
  padding: 0.75rem;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: auto;
  max-height: 14rem;
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 0.78rem;
  line-height: 1.45;
}

.metrics h3,
.sample-rows h3 {
  font-size: 0.9rem;
  margin: 0 0 0.45rem;
}

.metrics dl {
  margin: 0 0 1rem;
  display: grid;
  gap: 0.25rem;
}

.metric-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.5rem;
  font-size: 0.85rem;
  padding: 0.25rem 0;
  border-bottom: 1px solid var(--border);
}

.metric-row dt {
  color: var(--ink-muted);
  font-family: var(--font-mono);
  font-size: 0.78rem;
}

.table-scroll {
  overflow: auto;
  max-height: 16rem;
  border: 1px solid var(--border);
  border-radius: 8px;
}

.sample-rows table {
  border-collapse: collapse;
  font-size: 0.72rem;
  font-family: var(--font-mono);
  width: max-content;
  min-width: 100%;
}

.sample-rows th,
.sample-rows td {
  padding: 0.35rem 0.5rem;
  border-bottom: 1px solid var(--border);
  text-align: left;
  white-space: nowrap;
}

.sample-rows th {
  position: sticky;
  top: 0;
  background: var(--bg-soft);
  color: var(--ink-muted);
}

@media (max-width: 560px) {
  .app {
    padding: 0.85rem 0.75rem 2.5rem;
  }

  .top-bar {
    flex-direction: column;
  }

  .theme-toggle {
    align-self: flex-end;
  }

  .drawer-meta {
    grid-template-columns: 1fr;
  }

  .pipeline {
    min-height: 140px;
  }

  .wf-label {
    font-size: 9px;
  }
}

@media (max-width: 400px) {
  html {
    font-size: 16px;
  }

  .wordmark {
    font-size: 1.85rem;
  }

  .question-box,
  .timeline,
  .answer-card,
  .ruled-out,
  .rec-card,
  .memory-panel {
    padding: 0.9rem;
  }
}

success.afterFullFileContent:
:root,
[data-theme="light"] {
  --bg: #eef2f4;
  --bg-elev: #ffffff;
  --bg-soft: #e4eaee;
  --ink: #152028;
  --ink-muted: #5a6874;
  --accent: #0d6b5c;
  --accent-soft: #d5ebe5;
  --warn: #9a4d1c;
  --danger: #9b2c2c;
  --border: #c9d3da;
  --chip: #e2e8ec;
  --shadow: 0 1px 0 rgba(21, 32, 40, 0.05), 0 14px 36px rgba(21, 32, 40, 0.07);
  --wf-total: #152028;
  --wf-up: #c45c26;
  --wf-down: #0d6b5c;
  --wf-zero: #8a959e;
  --drawer-w: min(440px, 100vw);
  --font-display: "Fraunces", "Georgia", serif;
  --font-body: "Source Sans 3", "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;
  color-scheme: light;
}

[data-theme="dark"] {
  --bg: #10161a;
  --bg-elev: #182026;
  --bg-soft: #222c34;
  --ink: #e8eef2;
  --ink-muted: #9aabb8;
  --accent: #5fc4ae;
  --accent-soft: #1d3530;
  --warn: #e0a06a;
  --danger: #e09090;
  --border: #2e3a44;
  --chip: #243038;
  --shadow: 0 1px 0 rgba(0, 0, 0, 0.4), 0 16px 40px rgba(0, 0, 0, 0.4);
  --wf-total: #e8eef2;
  --wf-up: #e0a06a;
  --wf-down: #5fc4ae;
  --wf-zero: #6a7884;
  color-scheme: dark;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  font-size: 17px;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: var(--font-body);
  background:
    radial-gradient(ellipse 80% 50% at 10% -10%, color-mix(in srgb, var(--accent) 12%, transparent), transparent),
    radial-gradient(ellipse 60% 40% at 100% 0%, color-mix(in srgb, var(--warn) 8%, transparent), transparent),
    var(--bg);
  color: var(--ink);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

button,
textarea,
select,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

code,
pre {
  font-family: var(--font-mono);
  font-size: 0.85em;
}

.app {
  max-width: 920px;
  margin: 0 auto;
  padding: 1.25rem 1.1rem 3rem;
}

.top-bar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.theme-toggle {
  flex-shrink: 0;
  border: 1px solid var(--border);
  background: var(--bg-elev);
  border-radius: 999px;
  padding: 0.35rem 0.85rem;
  font-size: 0.85rem;
  color: var(--ink-muted);
}

.site-header {
  flex: 1;
  min-width: 0;
}

.wordmark {
  font-family: var(--font-display);
  font-weight: 650;
  font-size: clamp(2rem, 5vw, 2.6rem);
  letter-spacing: -0.02em;
  margin: 0 0 0.35rem;
  line-height: 1.1;
}

.tagline {
  margin: 0 0 0.9rem;
  color: var(--ink-muted);
  max-width: 36rem;
  font-size: 1.02rem;
}

.status-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.28rem 0.7rem;
  border-radius: 999px;
  background: var(--chip);
  font-size: 0.78rem;
  font-weight: 500;
  border: 1px solid transparent;
}

.chip.ok {
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border));
  background: var(--accent-soft);
}

.chip.warn {
  border-color: color-mix(in srgb, var(--warn) 40%, var(--border));
}

.offline-notice {
  margin: 0 0 1rem;
  padding: 0.55rem 0.85rem;
  border-radius: 8px;
  background: color-mix(in srgb, var(--warn) 14%, var(--bg-elev));
  border: 1px solid color-mix(in srgb, var(--warn) 35%, var(--border));
  color: var(--warn);
  font-size: 0.9rem;
}

.main {
  display: flex;
  flex-direction: column;
  gap: 1.35rem;
}

.question-box,
.timeline,
.answer-card,
.ruled-out,
.rec-card,
.clarify,
.memory-panel,
.how-answer,
.recent-answers {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.1rem 1.2rem 1.25rem;
  box-shadow: var(--shadow);
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

button:focus:not(:focus-visible),
a:focus:not(:focus-visible),
select:focus:not(:focus-visible),
textarea:focus:not(:focus-visible),
input:focus:not(:focus-visible) {
  outline: none;
}

.theme-toggle:focus-visible,
.ask-btn:focus-visible,
.suggestion:focus-visible,
.evidence-pill:focus-visible,
.cite:focus-visible,
.memory-toggle:focus-visible,
.text-btn:focus-visible,
.recent-item:focus-visible,
.llm-receipt-toggle:focus-visible,
.site-select select:focus-visible,
.note-form textarea:focus-visible,
.note-form button:focus-visible,
.icon-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.question-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.5rem;
}

.question-head label {
  font-weight: 600;
}

.sample-badge {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 0.2rem 0.55rem;
  border-radius: 4px;
  background: var(--bg-soft);
  border: 1px dashed var(--border);
  color: var(--ink-muted);
}

.question-box textarea {
  width: 100%;
  resize: vertical;
  min-height: 4.5rem;
  padding: 0.75rem 0.85rem;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--bg);
  outline: none;
}

.question-box textarea:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 22%, transparent);
}

.question-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: flex-end;
  margin-top: 0.75rem;
}

.site-select {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.85rem;
  color: var(--ink-muted);
  flex: 1;
  min-width: 160px;
}

.site-select select {
  padding: 0.55rem 0.7rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg);
}

.ask-btn {
  border: none;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  padding: 0.65rem 1.25rem;
  border-radius: 999px;
  min-height: 2.6rem;
}

[data-theme="dark"] .ask-btn {
  color: #10241c;
}

.ask-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.suggestions {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin-top: 0.9rem;
}

.suggestion {
  text-align: left;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.55rem 0.75rem;
  color: var(--ink-muted);
  font-size: 0.92rem;
}

.suggestion:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--ink);
}

.timeline h2,
.answer-card h2,
.ruled-out h2,
.rec-card h2,
.how-it-works h2,
.clarify h2 {
  font-family: var(--font-display);
  font-weight: 650;
  font-size: 1.35rem;
  margin: 0 0 0.75rem;
}

.timeline-stages {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.45rem;
}

.stage {
  display: grid;
  grid-template-columns: 14px 1fr auto;
  gap: 0.55rem;
  align-items: center;
  color: var(--ink-muted);
  font-size: 0.95rem;
}

.stage-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
}

.stage.active .stage-dot {
  background: var(--accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 25%, transparent);
}

.stage.done {
  color: var(--ink);
}

.stage.done .stage-dot {
  background: var(--accent);
}

.stage-ms {
  font-family: var(--font-mono);
  font-size: 0.78rem;
}

.llm-routes {
  list-style: none;
  margin: 1rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.4rem;
}

.llm-routes li {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 0.85rem;
  padding: 0.5rem 0.65rem;
  background: var(--bg-soft);
  border-radius: 8px;
  font-size: 0.88rem;
}

.llm-routes li.fallback {
  border: 1px solid color-mix(in srgb, var(--warn) 45%, var(--border));
}

.llm-step {
  font-weight: 600;
}

.llm-route {
  color: var(--ink-muted);
}

.llm-route.error {
  color: var(--danger);
}

.evidence-stream {
  margin-top: 1rem;
}

.evidence-stream h3 {
  margin: 0 0 0.5rem;
  font-size: 0.9rem;
  color: var(--ink-muted);
  font-weight: 600;
}

.evidence-stream ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.4rem;
}

.evidence-pill {
  width: 100%;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.35rem 0.65rem;
  text-align: left;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.55rem 0.7rem;
}

.ev-title {
  flex: 1;
  min-width: 10rem;
}

.ev-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.src-badge {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 0.15rem 0.45rem;
  border-radius: 4px;
  background: var(--chip);
  color: var(--ink-muted);
  white-space: nowrap;
}

.src-badge.muted {
  opacity: 0.75;
}

.timeline-done,
.timeline-reset {
  margin: 0.85rem 0 0;
  font-size: 0.9rem;
  color: var(--ink-muted);
}

.answer-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.5rem;
}

.answer-head h2 {
  margin: 0;
  flex: 1;
  min-width: 12rem;
}

.verify-badge {
  font-size: 0.78rem;
  font-weight: 600;
  padding: 0.35rem 0.7rem;
  border-radius: 999px;
  white-space: normal;
  max-width: 16rem;
  line-height: 1.3;
}

.verify-badge.ok {
  background: var(--accent-soft);
  color: var(--accent);
}

.verify-badge.template {
  background: var(--chip);
  color: var(--ink-muted);
}

.verify-badge.warn {
  background: color-mix(in srgb, var(--warn) 18%, transparent);
  color: var(--warn);
}

.waterfall {
  margin: 0.75rem 0 1rem;
}

.waterfall figcaption {
  font-size: 0.85rem;
  color: var(--ink-muted);
  margin-bottom: 0.35rem;
}

.waterfall svg {
  width: 100%;
  height: auto;
  display: block;
  background: var(--bg);
  border-radius: 10px;
  border: 1px solid var(--border);
}

.wf-value {
  fill: var(--ink);
  font-size: 11px;
  font-family: var(--font-mono);
}

.wf-label {
  fill: var(--ink-muted);
  font-size: 10px;
  font-family: var(--font-body);
}

.wf-connector {
  stroke: var(--border);
  stroke-dasharray: 3 3;
  stroke-width: 1;
}

.answer-body {
  display: grid;
  gap: 0.75rem;
}

.sentence {
  margin: 0;
}

.cite {
  display: inline-flex;
  align-items: center;
  margin: 0 0.15rem;
  padding: 0.05rem 0.4rem;
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: 0.78em;
  font-weight: 500;
  border: 1px solid var(--border);
  background: var(--bg-soft);
  vertical-align: baseline;
  line-height: 1.4;
}

button.cite {
  cursor: pointer;
}

.cite-e {
  border-color: color-mix(in srgb, var(--accent) 40%, var(--border));
  color: var(--accent);
}

.cite-f {
  cursor: help;
}

.cite-m {
  border-color: color-mix(in srgb, var(--warn) 40%, var(--border));
}

.cite-trail {
  display: inline;
  margin-left: 0.25rem;
}

.sample-note {
  margin: 1rem 0 0;
  font-size: 0.82rem;
  color: var(--ink-muted);
}

.ruled-chips {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.45rem;
}

.ruled-chip {
  width: 100%;
  text-align: left;
  display: grid;
  gap: 0.25rem;
  padding: 0.65rem 0.8rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg-soft);
  color: var(--ink-muted);
}

.ruled-hyp {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 600;
}

.ruled-text {
  font-size: 0.92rem;
  color: var(--ink);
}

.rec-card h3 {
  font-size: 1rem;
  margin: 1rem 0 0.4rem;
}

.muted {
  color: var(--ink-muted);
}

.small {
  font-size: 0.85rem;
}

.tariff-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.92rem;
  margin: 0.5rem 0;
}

.tariff-table th,
.tariff-table td {
  text-align: left;
  padding: 0.45rem 0.5rem;
  border-bottom: 1px solid var(--border);
}

.tariff-table th {
  color: var(--ink-muted);
  font-weight: 600;
  font-size: 0.8rem;
}

.error-banner {
  margin: 0;
  padding: 0.7rem 0.9rem;
  border-radius: 8px;
  background: color-mix(in srgb, var(--danger) 12%, var(--bg-elev));
  border: 1px solid color-mix(in srgb, var(--danger) 35%, var(--border));
  color: var(--danger);
}

.memory-toggle {
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  font-weight: 600;
  padding: 0;
  color: var(--ink);
}

.memory-body {
  margin-top: 0.85rem;
  display: grid;
  gap: 0.85rem;
}

.memory-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.65rem;
}

.memory-list li {
  padding: 0.65rem 0.75rem;
  border-radius: 8px;
  background: var(--bg);
  border: 1px solid var(--border);
}

.memory-list li.focus {
  border-color: var(--accent);
}

.note-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 0.85rem;
  font-size: 0.78rem;
  color: var(--ink-muted);
  margin-bottom: 0.35rem;
}

.note-form {
  display: grid;
  gap: 0.4rem;
}

.note-form textarea {
  width: 100%;
  padding: 0.6rem 0.7rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg);
  resize: vertical;
}

.note-form button,
.text-btn,
.icon-btn {
  border: 1px solid var(--border);
  background: var(--bg-soft);
  border-radius: 8px;
  padding: 0.45rem 0.8rem;
}

.text-btn {
  background: transparent;
  border: none;
  padding: 0;
  color: var(--accent);
  font-size: inherit;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.audit-pre {
  margin: 0;
  padding: 0.75rem;
  background: var(--bg);
  border-radius: 8px;
  overflow: auto;
  max-height: 12rem;
  font-size: 0.8rem;
}

.how-it-works {
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
}

.pipeline {
  width: 100%;
  height: auto;
  display: block;
  margin: 0.5rem 0 1rem;
}

.pipe-box {
  fill: var(--bg-elev);
  stroke: var(--border);
  stroke-width: 1.5;
}

.pipe-box.accent {
  fill: var(--accent-soft);
}

.pipe-title {
  fill: var(--ink);
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 650;
}

.pipe-line {
  fill: var(--ink-muted);
  font-family: var(--font-body);
  font-size: 11px;
}

.pipe-line.muted {
  fill: var(--ink-muted);
  font-size: 10px;
}

.pipe-arrow {
  stroke: var(--ink-muted);
  stroke-width: 1.5;
}

.built-with {
  font-size: 0.88rem;
  color: var(--ink-muted);
  margin: 0;
}

/* Evidence drawer */
.drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(20, 16, 12, 0.35);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
  z-index: 40;
}

.drawer-backdrop.show {
  opacity: 1;
  pointer-events: auto;
}

.evidence-drawer {
  position: fixed;
  top: 0;
  right: 0;
  width: var(--drawer-w);
  height: 100vh;
  background: var(--bg-elev);
  border-left: 1px solid var(--border);
  box-shadow: var(--shadow);
  z-index: 50;
  transform: translateX(105%);
  transition: transform 0.25s ease;
  overflow: auto;
  padding: 1.1rem 1.15rem 2rem;
}

.evidence-drawer.open {
  transform: translateX(0);
}

.drawer-head {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  align-items: flex-start;
}

.drawer-id {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--accent);
  font-weight: 600;
}

.drawer-head h2 {
  margin: 0.15rem 0 0;
  font-family: var(--font-display);
  font-size: 1.2rem;
}

.icon-btn {
  font-size: 1.4rem;
  line-height: 1;
  width: 2.2rem;
  height: 2.2rem;
  padding: 0;
  flex-shrink: 0;
}

.drawer-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin: 0.85rem 0;
}

.drawer-meta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.65rem;
  margin-bottom: 1rem;
  font-size: 0.88rem;
}

.meta-label {
  display: block;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ink-muted);
  margin-bottom: 0.15rem;
}

.sql-block {
  margin-bottom: 1rem;
}

.sql-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.35rem;
  font-size: 0.85rem;
  color: var(--ink-muted);
}

.sql-block pre {
  margin: 0;
  padding: 0.75rem;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: auto;
  max-height: 14rem;
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 0.78rem;
  line-height: 1.45;
}

.metrics h3,
.sample-rows h3 {
  font-size: 0.9rem;
  margin: 0 0 0.45rem;
}

.metrics dl {
  margin: 0 0 1rem;
  display: grid;
  gap: 0.25rem;
}

.metric-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.5rem;
  font-size: 0.85rem;
  padding: 0.25rem 0;
  border-bottom: 1px solid var(--border);
}

.metric-row dt {
  color: var(--ink-muted);
  font-family: var(--font-mono);
  font-size: 0.78rem;
}

.table-scroll {
  overflow: auto;
  max-height: 16rem;
  border: 1px solid var(--border);
  border-radius: 8px;
}

.sample-rows table {
  border-collapse: collapse;
  font-size: 0.72rem;
  font-family: var(--font-mono);
  width: max-content;
  min-width: 100%;
}

.sample-rows th,
.sample-rows td {
  padding: 0.35rem 0.5rem;
  border-bottom: 1px solid var(--border);
  text-align: left;
  white-space: nowrap;
}

.sample-rows th {
  position: sticky;
  top: 0;
  background: var(--bg-soft);
  color: var(--ink-muted);
}

@media (max-width: 560px) {
  .app {
    padding: 0.85rem 0.75rem 2.5rem;
  }

  .top-bar {
    flex-direction: column;
  }

  .theme-toggle {
    align-self: flex-end;
  }

  .drawer-meta {
    grid-template-columns: 1fr;
  }

  .pipeline {
    min-height: 140px;
  }

  .wf-label {
    font-size: 9px;
  }
}

@media (max-width: 400px) {
  html {
    font-size: 16px;
  }

  .wordmark {
    font-size: 1.85rem;
  }

  .question-box,
  .timeline,
  .answer-card,
  .ruled-out,
  .rec-card,
  .memory-panel {
    padding: 0.9rem;
  }
}
